class Foo {
  constructor(who) { this.me = who; }
  identify() { return 'I am ' + this.me; }
}
class Bar extends Foo {
  constructor(who) {
    super(who); // 呼叫 Foo 的 constructor
    this.label = 'Bar:' + who;
  }
  speak() {
    console.log(super.identify() + ', ' + this.label); // 呼叫 Foo 的 identify
  }
}
var b1 = new Bar('b1');
b1.speak();
console.log(b1 instanceof Foo, b1 instanceof Bar);

